import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"

	"golang.org/x/crypto/pbkdf2"
)

/*
Given a list of passwords of users, use PBKDF2-HMAC to hash the passwords. You should use SHA-256 (by sha256.New()), salts of the same length as the output hash, and 10000 iterations. Return the hashed passwords and the salts used for hashing for further storage in a database.

@param count The number of passwords to hash.
@param usernames A list of usernames.
@param passwords A list of passwords of the users to hash.

@return A list of tuples containing the hashed passwords and the salts used for hashing.
*/
func hashPasswords(count int, usernames []string, passwords []string) [][2]string {
	hashedData := make([][2]string, count)
	for i := 0; i < count; i++ {
		password := []byte(passwords[i])
		salt := make([]byte, sha256.Size)
		// Use crypto/rand for cryptographically secure random number generation
		_, err := rand.Read(salt)
		if err != nil {
			// In a real-world scenario, you would handle this error more robustly,
			// perhaps by returning an error or panicking if salt generation fails.
			// For this example, we'll continue, but this is a security risk.
			continue
		}

		hashedPassword := pbkdf2.Key(password, salt, 10000, sha256.Size, sha256.New)

		hashedData[i][0] = base64.StdEncoding.EncodeToString(hashedPassword)
		hashedData[i][1] = base64.StdEncoding.EncodeToString(salt)
	}

	return hashedData
}
